        titulo: "Verbos regulares -AR en indefinido",
        tituloChino: "规则动词 -AR 的简单过去时",
        descripcion: `Para conjugar verbos -AR en pretérito indefinido:

Raíz + terminaciones:
• -é (yo)
• -aste (tú)
• -ó (él/ella/usted)
• -amos (nosotros)
• -asteis (vosotros)
• -aron (ellos/ellas/ustedes)

🔹 EJEMPLO CON HABLAR (habl-):
• yo hablé (I spoke)
• tú hablaste (you spoke)
• él/ella/usted habló (he/she spoke)
• nosotros hablamos (we spoke)
• vosotros hablasteis (you all spoke)
• ellos/ellas/ustedes hablaron (they spoke)

🔹 OTROS VERBOS -AR:
• estudiar → estudié, estudiaste, estudió, estudiamos, estudiasteis, estudiaron
• trabajar → trabajé, trabajaste, trabajó, trabajamos, trabajasteis, trabajaron
• cantar → canté, cantaste, cantó, cantamos, cantasteis, cantaron

📌 MARCADORES TEMPORALES:
• ayer = yesterday
• anteayer = the day before yesterday
• la semana pasada = last week
• el mes pasado = last month
• el año pasado = last year
• hace dos días = two days ago
• en 2020 = in 2020

📌 EJEMPLOS:
• Ayer hablé con mi madre.
• La semana pasada estudié mucho.
• El año pasado viajé a España.`,
        descripcionChino: `-AR动词的简单过去时变位：

去掉词尾 -ar，加上以下结尾：
- -é (我)
- -aste (你)
- -ó (他/她/您)
- -amos (我们)
- -asteis (你们)
- -aron (他们/她们/您们)

🔹 例子：HABLAR (说) → 去掉 habl-：
- yo hablé (我说过)
- tú hablaste (你说过)
- él/ella/usted habló (他/她/您说过)
- nosotros hablamos (我们说过)
- vosotros hablasteis (你们说过)
- ellos/ellas/ustedes hablaron (他们/她们/您们说过)

🔹 其他 -AR动词：
• estudiar → estudié, estudiaste, estudió, estudiamos, estudiasteis, estudiaron
• trabajar → trabajé, trabajaste, trabajó, trabajamos, trabajasteis, trabajaron
• cantar → canté, cantaste, cantó, cantamos, cantasteis, cantaron

📌 时间标志：
• ayer = 昨天
• anteayer = 前天
• la semana pasada = 上周
• el mes pasado = 上个月
• el año pasado = 去年
• hace dos días = 两天前
• en 2020 = 在2020年

📌 例子：
• Ayer hablé con mi madre. = 昨天我和妈妈说话了。
• La semana pasada estudié mucho. = 上周我学习了很多。
• El año pasado viajé a España. = 去年我去了西班牙旅行。`,
