        tituloChino: "规则动词 -ER / -IR 的简单过去时",
        descripcion: `Para conjugar verbos -ER/-IR en pretérito indefinido:

Raíz + terminaciones:
• -í (yo)
• -iste (tú)
• -ió (él/ella/usted)
• -imos (nosotros)
• -isteis (vosotros)
• -ieron (ellos/ellas/ustedes)

🔹 EJEMPLO CON COMER (com-):
• yo comí (I ate)
• tú comiste (you ate)
• él/ella/usted comió (he/she ate)
• nosotros comimos (we ate)
• vosotros comisteis (you all ate)
• ellos/ellas/ustedes comieron (they ate)

🔹 EJEMPLO CON VIVIR (viv-):
• yo viví (I lived)
• tú viviste (you lived)
• él/ella/usted vivió (he/she lived)
• nosotros vivimos (we lived)
• vosotros vivisteis (you all lived)
• ellos/ellas/ustedes vivieron (they lived)

🔹 OTROS VERBOS -ER/-IR:
• beber → bebí, bebiste, bebió, bebimos, bebisteis, bebieron
• escribir → escribí, escribiste, escribió, escribimos, escribisteis, escribieron
• recibir → recibí, recibiste, recibió, recibimos, recibisteis, recibieron

📌 EJEMPLOS:
• Ayer comí paella.
• Tú viviste en Madrid.
• Ella escribió una carta.`,
        descripcionChino: `-ER/-IR动词的简单过去时变位：

去掉词尾 -er/-ir，加上以下结尾：
- -í (我)
- -iste (你)
- -ió (他/她/您)
- -imos (我们)
- -isteis (你们)
- -ieron (他们/她们/您们)

🔹 例子：COMER (吃) → 去掉 com-：
- yo comí (我吃过)
- tú comiste (你吃过)
- él/ella/usted comió (他/她/您吃过)
- nosotros comimos (我们吃过)
- vosotros comisteis (你们吃过)
- ellos/ellas/ustedes comieron (他们/她们/您们吃过)

🔹 例子：VIVIR (住) → 去掉 viv-：
- yo viví (我住过)
- tú viviste (你住过)
- él/ella/usted vivió (他/她/您住过)
- nosotros vivimos (我们住过)
- vosotros vivisteis (你们住过)
- ellos/ellas/ustedes vivieron (他们/她们/您们住过)

🔹 其他 -ER/-IR动词：
• beber → bebí, bebiste, bebió, bebimos, bebisteis, bebieron
• escribir → escribí, escribiste, escribió, escribimos, escribisteis, escribieron
• recibir → recibí, recibiste, recibió, recibimos, recibisteis, recibieron

📌 例子：
• Ayer comí paella. = 昨天我吃了海鲜饭。
• Tú viviste en Madrid. = 你在马德里住过。
• Ella escribió una carta. = 她写了一封信。`,
