        id: "t4",
        titulo: "Usos del pretérito indefinido",
        tituloChino: "简单过去时的用法",
        descripcion: `Se usa el pretérito indefinido para:

🔹 1. ACCIONES PASADAS COMPLETADAS (completed past actions):
   • Ayer compré un libro.
   • La semana pasada visité a mis abuelos.

🔹 2. ACCIONES QUE INTERRUMPEN OTRAS (actions that interrupt):
   • Cuando llegué, ella ya se había ido.
   • Sonó el teléfono mientras cenaba.

🔹 3. SECUENCIA DE ACCIONES EN EL PASADO (sequence of past actions):
   • Llegué, entré y me senté.
   • Me levanté, desayuné y salí de casa.

🔹 4. CAMBIOS EN EL PASADO (changes in the past):
   • Dejé de fumar el año pasado.
   • Me mudé a Madrid en 2019.

📌 DIFERENCIA CON EL PRETÉRITO PERFECTO:

| Aspecto | Indefinido | Perfecto |
|---------|------------|----------|
| Tiempo | Pasado lejano/completado | Pasado reciente/relevante |
| Marcadores | ayer, la semana pasada, en 2020 | hoy, esta semana, ya, nunca |
| Ejemplo | Ayer comí paella | Hoy he comido paella |

📌 MARCOS TEMPORALES TÍPICOS:
• ayer (yesterday)
• anteayer (day before yesterday)
• la semana pasada (last week)
• el mes pasado (last month)
• el año pasado (last year)
• hace + tiempo (ago)
• en + año (in + year)

❌ ERROR COMÚN:
No uses el indefinido con "hoy" o "esta semana". Usa el pretérito perfecto.`,
        descripcionChino: `简单过去时的用法：

🔹 1. 已完成的过去动作：
   • Ayer compré un libro. = 昨天我买了一本书。
   • La semana pasada visité a mis abuelos. = 上周我去看望了我的祖父母。

🔹 2. 打断其他动作的动作：
   • Cuando llegué, ella ya se había ido. = 当我到的时候，她已经走了。
   • Sonó el teléfono mientras cenaba. = 电话在晚餐时响了。

🔹 3. 过去动作的序列：
   • Llegué, entré y me senté. = 我到了，进去，坐下。
   • Me levanté, desayuné y salí de casa. = 我起床、吃早餐、出门。

🔹 4. 过去的变化：
   • Dejé de fumar el año pasado. = 我去年戒烟了。
   • Me mudé a Madrid en 2019. = 我在2019年搬到了马德里。

📌 与现在完成时的区别：

| 方面 | 简单过去时 | 现在完成时 |
|------|-----------|-----------|
| 时间 | 遥远过去/已完成 | 近期过去/与现在相关 |
| 标志 | ayer, la semana pasada, en 2020 | hoy, esta semana, ya, nunca |
| 例子 | Ayer comí paella | Hoy he comido paella |

📌 典型时间标志：
• ayer = 昨天
• anteayer = 前天
• la semana pasada = 上周
• el mes pasado = 上个月
• el año pasado = 去年
• hace + 时间 = ...前
• en + 年份 = 在...年

❌ 常见错误：
不要把简单过去时与"hoy"或"esta semana"连用。使用现在完成时。`,
