        tituloChino: "规则动词的过去未完成时",
        descripcion: `🔹 VERBOS -AR:
• -aba, -abas, -aba, -ábamos, -abais, -aban

EJEMPLO CON HABLAR:
• yo hablaba (I used to speak / I was speaking)
• tú hablabas
• él/ella/usted hablaba
• nosotros hablábamos
• vosotros hablabais
• ellos/ellas/ustedes hablaban

🔹 VERBOS -ER/-IR:
• -ía, -ías, -ía, -íamos, -íais, -ían

EJEMPLO CON COMER:
• yo comía (I used to eat / I was eating)
• tú comías
• él/ella/usted comía
• nosotros comíamos
• vosotros comíais
• ellos/ellas/ustedes comían

EJEMPLO CON VIVIR:
• yo vivía
• tú vivías
• él/ella/usted vivía
• nosotros vivíamos
• vosotros vivíais
• ellos/ellas/ustedes vivían

📌 EJEMPLOS:
• Cuando era niño, jugaba en el parque.
• Mi abuela cocinaba muy bien.
• Todos los días estudiaba español.`,
        descripcionChino: `🔹 -AR动词：
• -aba, -abas, -aba, -ábamos, -abais, -aban

例子：HABLAR (说)：
- yo hablaba (我说/过去常常说)
- tú hablabas
- él/ella/usted hablaba
- nosotros hablábamos
- vosotros hablabais
- ellos/ellas/ustedes hablaban

🔹 -ER/-IR动词：
• -ía, -ías, -ía, -íamos, -íais, -ían

例子：COMER (吃)：
- yo comía (我吃/过去常常吃)
- tú comías
- él/ella/usted comía
- nosotros comíamos
- vosotros comíais
- ellos/ellas/ustedes comían

例子：VIVIR (住)：
- yo vivía
- tú vivías
- él/ella/usted vivía
- nosotros vivíamos
- vosotros vivíais
- ellos/ellas/ustedes vivían

📌 例子：
• Cuando era niño, jugaba en el parque. = 当我还是孩子时，我常在公园玩。
• Mi abuela cocinaba muy bien. = 我祖母做饭很好吃。
• Todos los días estudiaba español. = 我每天都学西班牙语。`,
