        id: "t3",
        titulo: "Usos del imperfecto",
        tituloChino: "过去未完成时的用法",
        descripcion: `Se usa el imperfecto para:

🔹 1. HÁBITOS EN EL PASADO (acciones repetitivas):
   • Todos los días desayunaba café.
   • Cada verano viajaba a la playa.
   • Siempre llegaba tarde.

🔹 2. DESCRIPCIONES EN EL PASADO (personas, lugares, situaciones):
   • Mi abuela era alta y rubia.
   • La casa era grande y bonita.
   • El jardín tenía muchas flores.

🔹 3. EDAD EN EL PASADO:
   • Cuando tenía diez años...
   • A los quince años vivía en Madrid.

🔹 4. ACCIONES SIMULTÁNEAS EN EL PASADO:
   • Mientras estudiaba, escuchaba música.
   • Mientras ella cocinaba, él leía el periódico.

🔹 5. "BACKGROUND" ANTES DE UNA ACCIÓN PUNTUAL:
   • Hacía sol cuando llegué.
   • Estaba durmiendo cuando sonó el teléfono.

🔹 6. EXPRESAR CORTESÍA (en lugar de presente):
   • Quería pedirte un favor. (I wanted to ask you a favor)
   • Venía a ver si estaba usted. (I came to see if you were here)

📌 MARCADORES TÍPICOS:
• siempre = always
• todos los días = every day
• cada semana = each week
• antes = before
• de pequeño = as a child
• de niño = as a kid
• normalmente = normally
• generalmente = generally
• frecuentemente = frequently
• a menudo = often

📌 EJEMPLOS:
• Cuando era niño, jugaba al fútbol.
• De pequeño, vivía en el campo.
• Siempre llegaba tarde.`,
        descripcionChino: `过去未完成时的用法：

🔹 1. 过去的习惯（重复的动作）：
   • Todos los días desayunaba café. = 我每天都喝咖啡。
   • Cada verano viajaba a la playa. = 每年夏天我都去海滩。
   • Siempre llegaba tarde. = 他总是迟到。

🔹 2. 过去的描述（人、地方、情况）：
   • Mi abuela era alta y rubia. = 我祖母很高，金发。
   • La casa era grande y bonita. = 房子又大又漂亮。
   • El jardín tenía muchas flores. = 花园里有很多花。

🔹 3. 过去的年龄：
   • Cuando tenía diez años... = 当我十岁的时候...
   • A los quince años vivía en Madrid. = 十五岁时我住在马德里。

🔹 4. 过去同时发生的动作：
   • Mientras estudiaba, escuchaba música. = 我学习的时候听音乐。
   • Mientras ella cocinaba, él leía el periódico. = 她做饭的时候，他在读报纸。

🔹 5. 在具体动作之前的背景：
   • Hacía sol cuando llegué. = 我到的时候天气晴朗。
   • Estaba durmiendo cuando sonó el teléfono. = 电话响的时候我正在睡觉。

🔹 6. 表达礼貌（代替现在时）：
   • Quería pedirte un favor. = 我想请你帮个忙。
   • Venía a ver si estaba usted. = 我来看看您是否在。

📌 典型时间标志：
• siempre = 总是
• todos los días = 每天
• cada semana = 每周
• antes = 以前
• de pequeño = 小时候
• de niño = 童年时
• normalmente = 通常
• generalmente = 一般来说
• frecuentemente = 经常
• a menudo = 常常

📌 例子：
• Cuando era niño, jugaba al fútbol. = 我小时候踢足球。
• De pequeño, vivía en el campo. = 小时候我住在乡下。
• Siempre llegaba tarde. = 他总是迟到。`,
