        id: "t2",
        titulo: "Verbos irregulares en futuro simple",
        tituloChino: "不规则动词的简单将来时",
        descripcion: `Los verbos irregulares cambian la raíz pero mantienen las terminaciones:

🔹 LISTA DE VERBOS IRREGULARES EN FUTURO:

| Verbo | Raíz irregular | Ejemplo (yo) |
|-------|----------------|---------------|
| decir | dir- | diré |
| hacer | har- | haré |
| poder | podr- | podré |
| poner | pondr- | pondré |
| querer | querr- | querré |
| saber | sabr- | sabré |
| salir | saldr- | saldré |
| tener | tendr- | tendré |
| valer | valdr- | valdré |
| venir | vendr- | vendré |

🔹 CONJUGACIONES COMPLETAS:
• decir: diré, dirás, dirá, diremos, diréis, dirán
• hacer: haré, harás, hará, haremos, haréis, harán
• poder: podré, podrás, podrá, podremos, podréis, podrán
• tener: tendré, tendrás, tendrá, tendremos, tendréis, tendrán
• venir: vendré, vendrás, vendrá, vendremos, vendréis, vendrán

📌 EJEMPLOS:
• Te diré la verdad.
• ¿Podrás ayudarme mañana?
• Tendré mucho trabajo.
• Vendré a la fiesta.

❌ ERROR COMÚN:
No confundas el futuro simple con el futuro próximo (ir a + infinitivo). Ambos son correctos, pero el futuro simple es más formal y se usa para predicciones.`,
        descripcionChino: `不规则动词的词根发生变化，但结尾保持不变：

🔹 将来时中不规则动词列表：

| 动词 | 不规则词根 | 例子 (yo) |
|------|-----------|-----------|
| decir (说) | dir- | diré |
| hacer (做) | har- | haré |
| poder (能) | podr- | podré |
| poner (放) | pondr- | pondré |
| querer (想要) | querr- | querré |
| saber (知道) | sabr- | sabré |
| salir (出去) | saldr- | saldré |
| tener (有) | tendr- | tendré |
| valer (值) | valdr- | valdré |
| venir (来) | vendr- | vendré |

🔹 完整变位：
• decir: diré, dirás, dirá, diremos, diréis, dirán
• hacer: haré, harás, hará, haremos, haréis, harán
• poder: podré, podrás, podrá, podremos, podréis, podrán
• tener: tendré, tendrás, tendrá, tendremos, tendréis, tendrán
• venir: vendré, vendrás, vendrá, vendremos, vendréis, vendrán

📌 例子：
• Te diré la verdad. = 我会告诉你真相。
• ¿Podrás ayudarme mañana? = 你明天能帮我吗？
• Tendré mucho trabajo. = 我会有很多工作。
• Vendré a la fiesta. = 我会来派对。

❌ 常见错误：
不要混淆简单将来时和最近将来时（ir a + 动词原形）。两者都正确，但简单将来时更正式，用于预测。`,
