        id: "t4",
        titulo: "Futuro simple vs Futuro próximo",
        tituloChino: "简单将来时 vs 最近将来时",
        descripcion: `Diferencia entre el futuro simple y el futuro próximo:

🔹 FUTURO PRÓXIMO (ir a + infinitivo):
• Más común en el habla cotidiana
• Para planes inmediatos o cercanos
• Expresa intención

Ejemplos:
• Voy a comer ahora. (I'm going to eat now)
• Esta tarde voy a ir al cine. (I'm going to the cinema this afternoon)

🔹 FUTURO SIMPLE (infinitivo + terminaciones):
• Más formal
• Para predicciones y suposiciones
• Para promesas
• Para acciones más lejanas

Ejemplos:
• Comeré más tarde. (I will eat later)
• Mañana iré al cine. (I will go to the cinema tomorrow)

📌 TABLA COMPARATIVA:

| Situación | Futuro Próximo | Futuro Simple |
|-----------|----------------|----------------|
| Plan inmediato | Voy a llamar ahora | — |
| Predicción | — | Llegará tarde |
| Promesa | Te voy a ayudar | Te ayudaré |
| Plan lejano | — | El año que viene viajaré |

📌 EJEMPLOS:
• Esta noche voy a cenar con amigos. (plan cercano)
• El año que viene trabajaré en otra empresa. (plan lejano)
• Creo que mañana lloverá. (predicción)
• No te preocupes, te voy a ayudar / te ayudaré. (ambos posibles)

❌ NOTA:
En España, el futuro próximo es cada vez más común, incluso para acciones lejanas. El futuro simple se reserva para predicciones, promesas y contextos formales.`,
        descripcionChino: `简单将来时和最近将来时的区别：

🔹 最近将来时（ir a + 动词原形）：
• 日常口语中更常见
• 用于近期或眼前的计划
• 表达意图

例子：
• Voy a comer ahora. = 我现在要吃。
• Esta tarde voy a ir al cine. = 今天下午我要去电影院。

🔹 简单将来时（动词原形 + 结尾）：
• 更正式
• 用于预测和假设
• 用于承诺
• 用于更遥远的动作

例子：
• Comeré más tarde. = 我晚点会吃。
• Mañana iré al cine. = 我明天会去电影院。

📌 比较表：

| 情况 | 最近将来时 | 简单将来时 |
|------|-----------|-----------|
| 近期计划 | Voy a llamar ahora | — |
| 预测 | — | Llegará tarde |
| 承诺 | Te voy a ayudar | Te ayudaré |
| 远期计划 | — | El año que viene viajaré |

📌 例子：
• Esta noche voy a cenar con amigos. = 今晚我要和朋友吃晚餐。（近期计划）
• El año que viene trabajaré en otra empresa. = 明年我会在其他公司工作。（远期计划）
• Creo que mañana lloverá. = 我认为明天会下雨。（预测）
• No te preocupes, te voy a ayudar / te ayudaré. = 别担心，我会帮你。（两者都可以）

📌 注意：
在西班牙，最近将来时越来越常见，即使对于遥远的动作也是如此。简单将来时则保留用于预测、承诺和正式场合。`,
