    numeroTexto: "cuarenta y cuatro",
    titulo: "Imperativo - Dar Órdenes y Consejos",
    tituloChino: "命令式 - 发出命令和建议",
    descripcion: "学习用西班牙语发出命令、请求、建议和指示。",
    descripcionChino: "学习用西班牙语发出命令、请求、建议和指示",
