        tituloChino: "肯定命令式 - USTED（正式）",
        descripcion: `Para dar órdenes o consejos de forma formal (usted):

🔹 VERBOS -AR: quita la -AR, añada -E
• hablar → ¡Hable!
• estudiar → ¡Estudie!
• trabajar → ¡Trabaje!
• cantar → ¡Cante!
• bailar → ¡Baille!

🔹 VERBOS -ER/-IR: quita la -ER/-IR, añada -A
• comer → ¡Coma!
• beber → ¡Beba!
• vivir → ¡Viva!
• escribir → ¡Escriba!
• salir → ¡Salga!

🔹 VERBOS IRREGULARES MÁS COMUNES (usted):

| Verbo | Imperativo | Ejemplo |
|-------|------------|---------|
| decir | ¡Diga! | ¡Diga la verdad! |
| hacer | ¡Haga! | ¡Haga el favor! |
| ir | ¡Vaya! | ¡Vaya a su casa! |
| poner | ¡Ponga! | ¡Ponga atención! |
| salir | ¡Salga! | ¡Salga de aquí! |
| ser | ¡Sea! | ¡Sea paciente! |
| tener | ¡Tenga! | ¡Tenga cuidado! |
| venir | ¡Venga! | ¡Venga a la oficina! |

📌 EJEMPLOS:
• ¡Hable más despacio, por favor!
• ¡Coma más verduras!
• ¡Venga a mi oficina!

❌ DIFERENCIA CLAVE:
El imperativo de "usted" se forma usando la tercera persona del singular del subjuntivo presente.`,
        descripcionChino: `正式地发出命令或建议（usted形式）：

🔹 -AR动词：去掉-AR，加上-E
• hablar (说) → ¡Hable! (您说！)
• estudiar (学习) → ¡Estudie! (您学习！)
• trabajar (工作) → ¡Trabaje! (您工作！)
• cantar (唱歌) → ¡Cante! (您唱！)
• bailar (跳舞) → ¡Baille! (您跳！)

🔹 -ER/-IR动词：去掉-ER/-IR，加上-A
• comer (吃) → ¡Coma! (您吃！)
• beber (喝) → ¡Beba! (您喝！)
• vivir (住) → ¡Viva! (您住！)
• escribir (写) → ¡Escriba! (您写！)
• salir (出去) → ¡Salga! (您出去！)

🔹 最常见的不规则动词（usted）：

| 动词 | 命令式 | 例子 |
|------|--------|------|
| decir | ¡Diga! | ¡Diga la verdad! (您说实话！) |
| hacer | ¡Haga! | ¡Haga el favor! (请帮忙！) |
| ir | ¡Vaya! | ¡Vaya a su casa! (您回家！) |
| poner | ¡Ponga! | ¡Ponga atención! (您注意！) |
| salir | ¡Salga! | ¡Salga de aquí! (您出去！) |
| ser | ¡Sea! | ¡Sea paciente! (您耐心点！) |
| tener | ¡Tenga! | ¡Tenga cuidado! (您小心！) |
| venir | ¡Venga! | ¡Venga a la oficina! (您来办公室！) |

📌 例子：
• ¡Hable más despacio, por favor! = 请您说慢一点！
• ¡Coma más verduras! = 请您多吃蔬菜！
• ¡Venga a mi oficina! = 请您来我的办公室！

❌ 关键区别：
"usted"的命令式使用虚拟式现在时的第三人称单数形式构成。`,
