        descripcion: `Para decir que NO hagas algo:

NO + subjuntivo (presente)

🔹 TÚ (informal) - negativo:
• hablar → ¡No hables!
• comer → ¡No comas!
• vivir → ¡No vivas!
• ir → ¡No vayas!
• hacer → ¡No hagas!
• decir → ¡No digas!
• salir → ¡No salgas!
• poner → ¡No pongas!
• venir → ¡No vengas!
• tener → ¡No tengas!

🔹 USTED (formal) - negativo:
• hablar → ¡No hable!
• comer → ¡No coma!
• vivir → ¡No viva!
• ir → ¡No vaya!
• hacer → ¡No haga!

🔹 NOSOTROS (nosotros - "let's not"):
• hablar → ¡No hablemos!
• comer → ¡No comamos!
• ir → ¡No vayamos!
• hacer → ¡No hagamos!

🔹 VOSOTROS (informal plural - Spain):
• hablar → ¡No habléis!
• comer → ¡No comáis!
• vivir → ¡No viváis!

📌 EJEMPLOS:
• ¡No hables tan rápido!
• ¡No comas demasiado!
• ¡No vayas solo!
• ¡No se preocupen! (ustedes)

❌ IMPORTANTE:
El imperativo negativo usa las mismas formas para todos los verbos dentro del mismo tipo (-AR, -ER, -IR).`,
        descripcionChino: `告诉某人不要做某事：

NO + 虚拟式现在时

🔹 TÚ（非正式）- 否定：
• hablar (说) → ¡No hables! (你别说了！)
• comer (吃) → ¡No comas! (你别吃了！)
• vivir (住) → ¡No vivas! (你别住了！)
• ir (去) → ¡No vayas! (你别去！)
• hacer (做) → ¡No hagas! (你别做！)
• decir (说) → ¡No digas! (你别说！)
• salir (出去) → ¡No salgas! (你别出去！)
• poner (放) → ¡No pongas! (你别放！)
• venir (来) → ¡No vengas! (你别来！)
• tener (有) → ¡No tengas! (你别有！)

🔹 USTED（正式）- 否定：
• hablar → ¡No hable! (您别说！)
• comer → ¡No coma! (您别吃！)
• vivir → ¡No viva! (您别住！)
• ir → ¡No vaya! (您别去！)
• hacer → ¡No haga! (您别做！)

🔹 NOSOTROS（我们 - "让我们不要"）：
• hablar → ¡No hablemos! (我们别说！)
• comer → ¡No comamos! (我们别吃！)
• ir → ¡No vayamos! (我们别去！)
• hacer → ¡No hagamos! (我们别做！)

🔹 VOSOTROS（非正式复数 - 西班牙）：
• hablar → ¡No habléis! (你们别说！)
• comer → ¡No comáis! (你们别吃！)
• vivir → ¡No viváis! (你们别住！)

📌 例子：
• ¡No hables tan rápido! = 别说那么快！
• ¡No comas demasiado! = 别吃太多！
• ¡No vayas solo! = 别一个人去！
• ¡No se preocupen! = 您们别担心！

❌ 重要：
否定命令式在同一类型的动词中使用相同的形式。`,
