        descripcion: `Se usa el subjuntivo después de:

🔹 1. DESEOS (querer, esperar, desear, ojalá):
   • Quiero que estudies.
   • Espero que vengas.
   • Ojalá que llueva.
   • Deseo que tengas un buen día.

🔹 2. DUDAS (dudar, no creer, no pensar, no estar seguro):
   • Dudo que sea verdad.
   • No creo que llueva.
   • No pienso que sea fácil.
   • No estoy seguro de que venga.

🔹 3. EMOCIONES (alegrarse, temer, sentir, sorprender):
   • Me alegra que estés bien.
   • Siento que llegues tarde.
   • Me sorprende que digas eso.
   • Temo que no venga.

🔹 4. EXPRESIONES IMPERSONALES:
   • Es importante que estudies.
   • Es posible que venga.
   • Es necesario que descanses.
   • Es mejor que te vayas.

🔹 5. RECOMENDACIONES Y CONSEJOS:
   • Te sugiero que descanses.
   • Recomiendo que leas este libro.
   • Aconsejo que no vayas solo.

🔹 6. OJALÁ (expresar deseos):
   • Ojalá que llueva.
   • Ojalá venga mañana.
   • Ojalá pueda ayudarte.

📌 LISTA DE EXPRESIONES QUE RIGEN SUBJUNTIVO:
• esperar que
• querer que
• desear que
• necesitar que
• pedir que
• recomendar que
• sugerir que
• prohibir que
• es importante que
• es necesario que
• es posible que
• es probable que
• es mejor que
• ojalá que

❌ NOTA:
Las expresiones de certeza (creo que, estoy seguro de que, es cierto que) usan indicativo, no subjuntivo.`,
        descripcionChino: `虚拟式用于以下情况之后：

🔹 1. 愿望（querer, esperar, desear, ojalá）：
   • Quiero que estudies. = 我希望你学习。
   • Espero que vengas. = 我希望你来。
   • Ojalá que llueva. = 但愿下雨。
   • Deseo que tengas un buen día. = 我祝愿你有美好的一天。

🔹 2. 怀疑（dudar, no creer, no pensar, no estar seguro）：
   • Dudo que sea verdad. = 我怀疑这是真的。
   • No creo que llueva. = 我不相信会下雨。
   • No pienso que sea fácil. = 我不认为这容易。
   • No estoy seguro de que venga. = 我不确定他会来。

🔹 3. 情感（alegrarse, temer, sentir, sorprender）：
   • Me alegra que estés bien. = 我很高兴你很好。
   • Siento que llegues tarde. = 很遗憾你迟到了。
   • Me sorprende que digas eso. = 你这么说让我惊讶。
   • Temo que no venga. = 我担心他不来。

🔹 4. 无人称表达：
   • Es importante que estudies. = 重要的是你学习。
   • Es posible que venga. = 他可能会来。
   • Es necesario que descanses. = 你需要休息。
   • Es mejor que te vayas. = 你最好离开。

🔹 5. 推荐和建议：
   • Te sugiero que descanses. = 我建议你休息。
   • Recomiendo que leas este libro. = 我推荐你读这本书。
   • Aconsejo que no vayas solo. = 我建议你不要一个人去。

🔹 6. OJALÁ（表达愿望）：
   • Ojalá que llueva. = 但愿下雨。
   • Ojalá venga mañana. = 但愿他明天来。
   • Ojalá pueda ayudarte. = 但愿我能帮你。

📌 带虚拟式的表达列表：
• esperar que = 希望
• querer que = 想要
• desear que = 愿望
• necesitar que = 需要
• pedir que = 请求
• recomendar que = 推荐
• sugerir que = 建议
• prohibir que = 禁止
• es importante que = 重要的是
• es necesario que = 有必要
• es posible que = 可能
• es probable que = 很可能
• es mejor que = 最好
• ojalá que = 但愿

❌ 注意：
确定性表达（creo que, estoy seguro de que, es cierto que）使用陈述式，而不是虚拟式。`,
