        id: "t4",
        titulo: "Indicativo vs Subjuntivo",
        tituloChino: "陈述式 vs 虚拟式",
        descripcion: `Diferencia entre indicativo y subjuntivo:

🔹 INDICATIVO (hechos, certezas):
• Creo que (I believe that)
• Pienso que (I think that)
• Estoy seguro de que (I'm sure that)
• Es cierto que (It's certain that)
• Es verdad que (It's true that)
• No dudo que (I don't doubt that)

EJEMPLOS:
• Creo que María viene a la fiesta.
• Es cierto que el café contiene cafeína.
• No dudo que tienes razón.

🔹 SUBJUNTIVO (deseos, dudas, emociones):
• Espero que (I hope that)
• Quiero que (I want that)
• Dudo que (I doubt that)
• No creo que (I don't think that)
• Me alegra que (I'm glad that)
• Es posible que (It's possible that)

EJEMPLOS:
• Espero que María venga a la fiesta.
• Dudo que tenga razón.
• Me alegra que estés bien.

📌 TABLA COMPARATIVA:

| Expresión | Tipo | Modo | Ejemplo |
|-----------|------|------|---------|
| Creo que | certeza | Indicativo | Creo que viene |
| No creo que | duda | Subjuntivo | No creo que venga |
| Es cierto que | certeza | Indicativo | Es cierto que llueve |
| Es posible que | posibilidad | Subjuntivo | Es posible que llueva |
| Estoy seguro de que | certeza | Indicativo | Estoy seguro de que ganará |
| Dudo que | duda | Subjuntivo | Dudo que gane |

❌ ERROR COMÚN:
Después de "quizás" y "tal vez" se puede usar indicativo o subjuntivo:
• Quizás viene (más seguro)
• Quizás venga (menos seguro)`,
        descripcionChino: `陈述式和虚拟式的区别：

🔹 陈述式（事实、确定性）：
• Creo que = 我认为
• Pienso que = 我想
• Estoy seguro de que = 我确定
• Es cierto que = 确实
• Es verdad que = 真的
• No dudo que = 我不怀疑

例子：
• Creo que María viene a la fiesta. = 我认为玛丽亚会来派对。
• Es cierto que el café contiene cafeína. = 咖啡确实含有咖啡因。
• No dudo que tienes razón. = 我不怀疑你是对的。

🔹 虚拟式（愿望、怀疑、情感）：
• Espero que = 我希望
• Quiero que = 我想要
• Dudo que = 我怀疑
• No creo que = 我不认为
• Me alegra que = 我很高兴
• Es posible que = 可能

例子：
• Espero que María venga a la fiesta. = 我希望玛丽亚来派对。
• Dudo que tenga razón. = 我怀疑他是对的。
• Me alegra que estés bien. = 我很高兴你很好。

📌 比较表：

| 表达 | 类型 | 语气 | 例子 |
|------|------|------|------|
| Creo que | 确定性 | 陈述式 | Creo que viene |
| No creo que | 怀疑 | 虚拟式 | No creo que venga |
| Es cierto que | 确定性 | 陈述式 | Es cierto que llueve |
| Es posible que | 可能性 | 虚拟式 | Es posible que llueva |
| Estoy seguro de que | 确定性 | 陈述式 | Estoy seguro de que ganará |
| Dudo que | 怀疑 | 虚拟式 | Dudo que gane |

❌ 常见错误：
在"quizás"和"tal vez"之后，可以使用陈述式或虚拟式：
• Quizás viene（更确定）
• Quizás venga（不太确定）`,
