        tituloChino: "真实条件句（类型1）",
        descripcion: `Expresa una condición posible y real:

🔹 ESTRUCTURA: Si + presente de indicativo, + presente / futuro / imperativo

📌 EJEMPLOS:
• Si estudias, aprobarás.
• Si llueve, no salgo.
• Si tienes hambre, come algo.
• Si terminas pronto, te llamo.
• Si necesitas ayuda, dímelo.

🔹 USOS:
• Si + presente, + futuro (consecuencia probable)
• Si + presente, + presente (verdad general)
• Si + presente, + imperativo (consejo)

📌 EJEMPLOS ADICIONALES:
• Si hace buen tiempo, iremos a la playa.
• Si llega tarde, empezamos sin él.
• Si quieres, puedes quedarte.
• Si no estudias, suspenderás.

❌ ERROR COMÚN:
En el tipo 1, después de "si" nunca se usa el futuro. Decimos "Si estudias" no "Si estudiarás".`,
        descripcionChino: `表达可能和真实的条件：

🔹 结构：Si + 陈述式现在时 + 现在时/将来时/命令式

📌 例子：
• Si estudias, aprobarás. = 如果你学习，你会通过。
• Si llueve, no salgo. = 如果下雨，我就不出去。
• Si tienes hambre, come algo. = 如果你饿了，吃点东西。
• Si terminas pronto, te llamo. = 如果你很快完成，我打电话给你。
• Si necesitas ayuda, dímelo. = 如果你需要帮助，告诉我。

🔹 用法：
• Si + 现在时 + 将来时（可能的结果）
• Si + 现在时 + 现在时（普遍真理）
• Si + 现在时 + 命令式（建议）

📌 更多例子：
• Si hace buen tiempo, iremos a la playa. = 如果天气好，我们会去海滩。
• Si llega tarde, empezamos sin él. = 如果他迟到，我们就不等他了。
• Si quieres, puedes quedarte. = 如果你愿意，你可以留下。
• Si no estudias, suspenderás. = 如果你不学习，你会不及格。

❌ 常见错误：
在类型1条件句中，"si"后面永远不用将来时。我们说"Si estudias"而不是"Si estudiarás"。`,
