        descripcion: `Expresa una condición imposible (pasado):

🔹 ESTRUCTURA: Si + pluscuamperfecto de subjuntivo, + condicional compuesto

📌 EJEMPLOS:
• Si hubiera estudiado, habría aprobado.
• Si hubiera sabido, habría venido.
• Si no hubiera llovido, habríamos ido a la playa.
• Si hubiera tenido dinero, habría comprado el coche.
• Si hubiera llegado a tiempo, lo habría visto.

🔹 USOS:
• Situaciones pasadas que no ocurrieron
• Arrepentimiento
• Crítica sobre el pasado

📌 NOTA:
• Pluscuamperfecto de subjuntivo: hubiera + participio
• Condicional compuesto: habría + participio

📌 EJEMPLOS ADICIONALES:
• Si me hubieras avisado, te habría esperado.
• Si no hubiera comido tanto, no estaría enfermo.
• Si hubiera estudiado medicina, sería doctor.
• Si hubiera sabido que venías, habría preparado la cena.

❌ ERROR COMÚN:
No confundas el pluscuamperfecto de subjuntivo (hubiera) con el pluscuamperfecto de indicativo (había).`,
        descripcionChino: `表达不可能的条件（过去）：

🔹 结构：Si + 虚拟式过去完成时 + 复合条件式

📌 例子：
• Si hubiera estudiado, habría aprobado. = 如果我当时学习了，我就会通过。
• Si hubiera sabido, habría venido. = 如果我知道，我就会来。
• Si no hubiera llovido, habríamos ido a la playa. = 如果没下雨，我们就会去海滩。
• Si hubiera tenido dinero, habría comprado el coche. = 如果当时我有钱，我就会买那辆车。
• Si hubiera llegado a tiempo, lo habría visto. = 如果我按时到了，我就会看到他。

🔹 用法：
• 过去没有发生的情况
• 后悔
• 对过去的批评

📌 注意：
• 虚拟式过去完成时：hubiera + 过去分词
• 复合条件式：habría + 过去分词

📌 更多例子：
• Si me hubieras avisado, te habría esperado. = 如果你当时通知我，我就会等你。
• Si no hubiera comido tanto, no estaría enfermo. = 如果我没吃那么多，就不会生病。
• Si hubiera estudiado medicina, sería doctor. = 如果我当时学了医，现在就是医生了。
• Si hubiera sabido que venías, habría preparado la cena. = 如果我知道你要来，我就会准备晚餐。

❌ 常见错误：
不要混淆虚拟式过去完成时（hubiera）和陈述式过去完成时（había）。`,
