        descripcion: `🔹 TABLA COMPARATIVA:

| Tipo | Si | Consecuencia | Uso | Ejemplo |
|------|----|--------------|-----|---------|
| 1 | Presente | Presente/Futuro/Imperativo | Real/Posible | Si estudias, apruebas |
| 2 | Imperfecto Subjuntivo | Condicional simple | Hipotético/Improbable | Si estudiara, aprobaría |
| 3 | Pluscuamperfecto Subjuntivo | Condicional compuesto | Imposible (pasado) | Si hubiera estudiado, habría aprobado |

📌 EJEMPLOS COMPARATIVOS:

MISMA IDEA EN TRES TIEMPOS:

• Tipo 1: Si tienes tiempo, ayúdame. (real)
• Tipo 2: Si tuvieras tiempo, me ayudarías. (hipotético)
• Tipo 3: Si hubieras tenido tiempo, me habrías ayudado. (imposible)

• Tipo 1: Si llueve, me quedo en casa.
• Tipo 2: Si lloviera, me quedaría en casa.
• Tipo 3: Si hubiera llovido, me habría quedado en casa.

🔹 EXPRESIONES COMUNES CON "SI":
• ¿Qué haces si...?
• ¿Qué harías si...?
• ¿Qué habrías hecho si...?
• Yo que tú...
• En tu lugar...

📌 NOTA IMPORTANTE:
La conjunción "si" nunca va seguida de condicional. Decimos "Si tuviera" no "Si tendría".`,
