        id: "t1",
        titulo: "Formación del pluscuamperfecto",
        tituloChino: "过去完成时的构成",
        descripcion: `El pretérito pluscuamperfecto se forma con:

HABER (imperfecto) + participio del verbo

Conjugación de HABER en imperfecto:
• yo HABÍA
• tú HABÍAS
• él/ella/usted HABÍA
• nosotros HABÍAMOS
• vosotros HABÍAIS
• ellos/ellas/ustedes HABÍAN

Participios regulares:
• -AR → -ADO: hablado, estudiado, trabajado
• -ER/-IR → -IDO: comido, bebido, vivido

🔹 EJEMPLOS:
• Yo había hablado con María.
• Tú habías comido paella.
• Él había vivido en Madrid.
• Nosotros habíamos estudiado.
• Ellos habían llegado tarde.

📌 ESTRUCTURA: HABER (imperfecto) + participio

❌ ERROR COMÚN:
No confundas el pluscuamperfecto (había + participio) con el pretérito perfecto (he + participio). El pluscuamperfecto es para "el pasado del pasado".`,
        descripcionChino: `过去完成时的构成：

HABER（过去未完成时）+ 动词的过去分词

HABER的过去未完成时变位：
- yo HABÍA = 我曾经
- tú HABÍAS = 你曾经
- él/ella/usted HABÍA = 他/她/您曾经
- nosotros HABÍAMOS = 我们曾经
- vosotros HABÍAIS = 你们曾经
- ellos/ellas/ustedes HABÍAN = 他们/她们/您们曾经

规则动词的过去分词：
- -AR动词 → -ADO：hablado (说了), estudiado (学习了)
- -ER/-IR动词 → -IDO：comido (吃了), bebido (喝了), vivido (住了)

🔹 例子：
• Yo había hablado con María. = 我之前和玛丽亚说过话。
• Tú habías comido paella. = 你之前吃过海鲜饭。
• Él había vivido en Madrid. = 他之前在马德里住过。
• Nosotros habíamos estudiado. = 我们之前学习过。
• Ellos habían llegado tarde. = 他们之前迟到了。

📌 结构：HABER（过去未完成时）+ 过去分词

❌ 常见错误：
不要混淆过去完成时（había + 过去分词）和现在完成时（he + 过去分词）。过去完成时用于"过去的过去"。`,
