        titulo: "Participios irregulares en pluscuamperfecto",
        tituloChino: "过去完成时中的不规则过去分词",
        descripcion: `Participios irregulares más comunes:

🔹 LISTA DE PARTICIPIOS IRREGULARES:

• abrir → abierto
• cubrir → cubierto
• decir → dicho
• escribir → escrito
• hacer → hecho
• morir → muerto
• poner → puesto
• romper → roto
• ver → visto
• volver → vuelto
• freír → frito
• resolver → resuelto
• devolver → devuelto
• descubrir → descubierto
• imprimir → impreso

🔹 EJEMPLOS:
• Ya había abierto la puerta.
• Nunca había visto esa película.
• Había escrito una carta.
• Ya había hecho los deberes.

📌 TRUCO PARA RECORDAR:
La mayoría de los participios irregulares terminan en -to, -so, -cho:
• -to: abierto, cubierto, muerto, roto
• -so: puesto, impreso
• -cho: dicho, hecho

❌ ERROR COMÚN:
No confundas el participio "hecho" (de hacer) con el adjetivo "hecho" (terminado).`,
