        tituloChino: "过去完成时的用法",
        descripcion: `Se usa el pluscuamperfecto para:

🔹 1. ACCIÓN PASADA ANTES DE OTRA ACCIÓN PASADA:
   • Cuando llegué a casa, mi madre ya había cocinado.
   • Antes de salir, había desayunado.
   • Cuando llegamos, la película ya había empezado.

🔹 2. EXPERIENCIAS PASADAS (antes de un momento específico):
   • Nunca había viajado en avión hasta el año pasado.
   • Ya había visto esa película dos veces.
   • No había comido nunca sushi antes de ese día.

🔹 3. EN ORACIONES CONDICIONALES (Tipo 3):
   • Si hubiera estudiado, habría aprobado.
   • Si hubiera sabido, habría venido.

🔹 4. CON "YA", "TODAVÍA NO", "NUNCA", "JAMÁS":
   • Ya había terminado cuando me llamaste.
   • Todavía no había comido cuando llegaste.
   • Nunca había estado en España.

📌 MARCADORES TÍPICOS:
• ya = already
• todavía no = not yet
• nunca = never
• jamás = never (emphatic)
• antes de = before
• después de = after
• cuando = when
• tan pronto como = as soon as

📌 EJEMPLOS:
• Ya había terminado cuando me llamaste.
• Todavía no había comido cuando llegaste.
• Nunca había estado en España.`,
        descripcionChino: `过去完成时的用法：

🔹 1. 另一个过去动作之前发生的动作：
   • Cuando llegué a casa, mi madre ya había cocinado. = 当我到家时，妈妈已经做好了饭。
   • Antes de salir, había desayunado. = 出门前，我吃了早餐。
   • Cuando llegamos, la película ya había empezado. = 我们到的时候，电影已经开始了。

🔹 2. 过去的经历（在某个特定时间点之前）：
   • Nunca había viajado en avión hasta el año pasado. = 直到去年我才坐过飞机。
   • Ya había visto esa película dos veces. = 那部电影我已经看过两次了。
   • No había comido nunca sushi antes de ese día. = 那天之前我从未吃过寿司。

🔹 3. 在条件句中使用（类型3）：
   • Si hubiera estudiado, habría aprobado. = 如果我当时学习了，我就会通过。
   • Si hubiera sabido, habría venido. = 如果我知道，我就会来。

🔹 4. 与"YA"、"TODAVÍA NO"、"NUNCA"、"JAMÁS"连用：
   • Ya había terminado cuando me llamaste. = 你打电话给我的时候我已经完成了。
   • Todavía no había comido cuando llegaste. = 你到的时候我还没吃。
   • Nunca había estado en España. = 我从未去过西班牙。

📌 典型时间标志：
• ya = 已经
• todavía no = 还没有
• nunca = 从未
• jamás = 从未（强调）
• antes de = 在...之前
• después de = 在...之后
• cuando = 当...时
• tan pronto como = 一...就...

📌 例子：
• Ya había terminado cuando me llamaste. = 你打电话给我的时候我已经完成了。
• Todavía no había comido cuando llegaste. = 你到的时候我还没吃。
• Nunca había estado en España. = 我从未去过西班牙。`,
