        titulo: "Pluscuamperfecto vs Otros tiempos pasados",
        tituloChino: "过去完成时 vs 其他过去时态",
        descripcion: `Comparación entre los diferentes tiempos pasados:

🔹 PLUSCUAMPERFECTO (había + participio)
• Acción anterior a otra acción pasada
• "El pasado del pasado"

Ejemplo: Cuando llegué, ella ya se había ido.

🔹 PRETÉRITO PERFECTO (he + participio)
• Pasado reciente o relevante hoy

Ejemplo: Hoy he llegado temprano.

🔹 PRETÉRITO INDEFINIDO (-é, -í, -ó...)
• Acción completada en el pasado

Ejemplo: Ayer llegué temprano.

🔹 IMPERFECTO (-aba, -ía...)
• Hábitos o descripciones en el pasado

Ejemplo: Cuando era niño, llegaba temprano.

📌 TABLA COMPARATIVA:

| Tiempo | Uso | Ejemplo | Traducción |
|--------|-----|---------|-------------|
| Pluscuamperfecto | Pasado anterior | Ya había comido | Ya había comido |
| Pretérito perfecto | Pasado reciente | He comido | He comido |
| Pretérito indefinido | Pasado completado | Comí | Comí |
| Imperfecto | Hábito pasado | Comía | Comía |

📌 EJEMPLOS EN CONTEXTO:
• Ayer comí paella. (acción concreta)
• De niño, comía paella los domingos. (hábito)
• Hoy he comido paella. (hoy)
• Cuando llegué a casa, ya había comido. (antes de otra acción)`,
        descripcionChino: `不同过去时态的比较：

🔹 过去完成时（había + 过去分词）
• 另一个过去动作之前的动作
• "过去的过去"

例子：Cuando llegué, ella ya se había ido. = 我到的时候，她已经走了。

🔹 现在完成时（he + 过去分词）
• 近期过去或与现在相关的动作

例子：Hoy he llegado temprano. = 今天我早到了。

🔹 简单过去时（-é, -í, -ó...）
• 过去完成的动作

例子：Ayer llegué temprano. = 昨天我早到了。

🔹 过去未完成时（-aba, -ía...）
• 过去的习惯或描述

例子：Cuando era niño, llegaba temprano. = 我小时候，我总是早到。

📌 比较表：

| 时态 | 用法 | 例子 | 翻译 |
|------|------|------|------|
| 过去完成时 | 过去的过去 | Ya había comido | 我已经吃了 |
| 现在完成时 | 近期过去 | He comido | 我吃了 |
| 简单过去时 | 已完成过去 | Comí | 我吃了 |
| 未完成时 | 过去习惯 | Comía | 我过去常吃 |

📌 上下文中的例子：
• Ayer comí paella. = 昨天我吃了海鲜饭。（具体动作）
• De niño, comía paella los domingos. = 小时候，我星期天吃海鲜饭。（习惯）
• Hoy he comido paella. = 今天我吃了海鲜饭。（今天）
• Cuando llegué a casa, ya había comido. = 我到家的时候，已经吃过了。（在另一动作之前）`,
