        id: "t1",
        titulo: "Formación del imperfecto de subjuntivo",
        tituloChino: "虚拟式过去未完成时的构成",
        descripcion: `El imperfecto de subjuntivo se forma:

1. Empieza con la tercera persona del plural (ellos) del pretérito indefinido
2. Quita la terminación -ron
3. Añade las terminaciones:
   • -ra, -ras, -ra, -ramos, -rais, -ran

🔹 EJEMPLO CON HABLAR (ellos hablaron → habla-):
• hablara, hablaras, hablara, habláramos, hablarais, hablaran

🔹 EJEMPLO CON COMER (ellos comieron → comie-):
• comiera, comieras, comiera, comiéramos, comierais, comieran

🔹 EJEMPLO CON VIVIR (ellos vivieron → vivie-):
• viviera, vivieras, viviera, viviéramos, vivierais, vivieran

🔹 FORMA ALTERNATIVA EN -SE (menos común pero correcta):
• hablase, hablases, hablase, hablásemos, hablaseis, hablasen
• comiese, comieses, comiese, comiésemos, comieseis, comiesen
• viviese, vivieses, viviese, viviésemos, vivieseis, viviesen

📌 EJEMPLOS:
• Si hablara español, trabajaría aquí.
• Quería que vinieras a la fiesta.
• Ojalá tuviera más tiempo.

❌ NOTA: La forma en -ra es mucho más común que la forma en -se en el español actual.`,
        descripcionChino: `虚拟式过去未完成时的构成：

1. 从简单过去时的第三人称复数（ellos）开始
2. 去掉结尾 -ron
3. 加上以下结尾：
   - -ra, -ras, -ra, -ramos, -rais, -ran

🔹 例子：HABLAR (说) → ellos hablaron → habla-：
- hablara, hablaras, hablara, habláramos, hablarais, hablaran

🔹 例子：COMER (吃) → ellos comieron → comie-：
- comiera, comieras, comiera, comiéramos, comierais, comieran

🔹 例子：VIVIR (住) → ellos vivieron → vivie-：
- viviera, vivieras, viviera, viviéramos, vivierais, vivieran

🔹 -SE形式的替代形式（不太常见但正确）：
- hablase, hablases, hablase, hablásemos, hablaseis, hablasen
- comiese, comieses, comiese, comiésemos, comieseis, comiesen
- viviese, vivieses, viviese, viviésemos, vivieseis, viviesen

📌 例子：
• Si hablara español, trabajaría aquí. = 如果我会说西班牙语，我会在这里工作。
• Quería que vinieras a la fiesta. = 我想让你来派对。
• Ojalá tuviera más tiempo. = 但愿我有更多时间。

❌ 注意：在当代西班牙语中，-ra形式比-se形式常见得多。`,
