        id: "t2",
        titulo: "Verbos irregulares en imperfecto de subjuntivo",
        tituloChino: "虚拟式过去未完成时中的不规则动词",
        descripcion: `Verbos irregulares comunes (misma raíz que en pretérito indefinido):

🔹 LISTA DE VERBOS IRREGULARES:

• ser/ir → fuera, fueras, fuera, fuéramos, fuerais, fueran
• estar → estuviera, estuvieras, estuviera, estuviéramos, estuvierais, estuvieran
• tener → tuviera, tuvieras, tuviera, tuviéramos, tuvierais, tuvieran
• hacer → hiciera, hicieras, hiciera, hiciéramos, hicierais, hicieran
• poder → pudiera, pudieras, pudiera, pudiéramos, pudierais, pudieran
• poner → pusiera, pusieras, pusiera, pusiéramos, pusierais, pusieran
• decir → dijera, dijeras, dijera, dijéramos, dijerais, dijeran
• venir → viniera, vinieras, viniera, viniéramos, vinierais, vinieran
• querer → quisiera, quisieras, quisiera, quisiéramos, quisierais, quisieran
• saber → supiera, supieras, supiera, supiéramos, supierais, supieran
• haber → hubiera, hubieras, hubiera, hubiéramos, hubierais, hubieran

🔹 EJEMPLOS:
• Si fuera rico, viajaría por el mundo.
• Quisiera que me ayudaras.
• Ojalá pudiera viajar más.

📌 TRUCO PARA RECORDAR:
La raíz del imperfecto de subjuntivo es la misma que la tercera persona del plural del pretérito indefinido (ellos).`,
        descripcionChino: `常见的不规则动词（与简单过去时相同的词根）：

🔹 不规则动词列表：

• ser/ir (是/去) → fuera, fueras, fuera, fuéramos, fuerais, fueran
• estar (在) → estuviera, estuvieras, estuviera, estuviéramos...
• tener (有) → tuviera, tuvieras, tuviera, tuviéramos...
• hacer (做) → hiciera, hicieras, hiciera, hiciéramos...
• poder (能) → pudiera, pudieras, pudiera, pudiéramos...
• poner (放) → pusiera, pusieras, pusiera, pusiéramos...
• decir (说) → dijera, dijeras, dijera, dijéramos...
• venir (来) → viniera, vinieras, viniera, viniéramos...
• querer (想要) → quisiera, quisieras, quisiera, quisiéramos...
• saber (知道) → supiera, supieras, supiera, supiéramos...
• haber (有) → hubiera, hubieras, hubiera, hubiéramos...

🔹 例子：
• Si fuera rico, viajaría por el mundo. = 如果我有钱，我会环游世界。
• Quisiera que me ayudaras. = 我希望你帮我。
• Ojalá pudiera viajar más. = 但愿我能多旅行。

📌 记忆技巧：
虚拟式过去未完成时的词根与简单过去时的第三人称复数（ellos）相同。`,
