        id: "t4",
        titulo: "Imperfecto de subjuntivo en cortesía",
        tituloChino: "礼貌用语中的虚拟式过去未完成时",
        descripcion: `El imperfecto de subjuntivo se usa frecuentemente para expresar cortesía:

🔹 CON "QUISIERA" (I would like):
• Quisiera un café, por favor.
• Quisiera pedir información sobre los horarios.
• Quisiera reservar una habitación.

🔹 CON "PUDIERA" (could I):
• ¿Pudiera ayudarme?
• ¿Pudiera pasar?

🔹 EN PREGUNTAS CORTESES:
• ¿Pudiera decirme la hora?
• ¿Pudiera indicarme cómo llegar?

📌 COMPARATIVO CON OTRAS FORMAS DE CORTESÍA:

| Nivel de cortesía | Expresión |
|-------------------|-----------|
| Estándar | ¿Puedes ayudarme? |
| Más cortés | ¿Podrías ayudarme? |
| Muy cortés | ¿Pudieras ayudarme? (menos común) |

📌 NOTA:
En el español actual, las formas más comunes de cortesía son el condicional (podrías, deberías) y "quisiera". El imperfecto de subjuntivo para cortesía es más común en contextos formales y en algunas regiones de América Latina.

❌ EJEMPLOS:
• Quisiera un café = I would like a coffee (muy cortés)
• Quisiera pedir la cuenta = I would like to ask for the bill`,
        descripcionChino: `虚拟式过去未完成时常用于表达礼貌：

🔹 用"QUISIERA"（我想要）：
• Quisiera un café, por favor. = 我想要一杯咖啡。
• Quisiera pedir información sobre los horarios. = 我想询问时间表的信息。
• Quisiera reservar una habitación. = 我想预订一个房间。

🔹 用"PUDIERA"（我可以）：
• ¿Pudiera ayudarme? = 您能帮我吗？
• ¿Pudiera pasar? = 我可以进来吗？

🔹 在礼貌问题中：
• ¿Pudiera decirme la hora? = 您能告诉我时间吗？
• ¿Pudiera indicarme cómo llegar? = 您能告诉我怎么走吗？

📌 与其他礼貌形式的比较：

| 礼貌程度 | 表达 |
|---------|------|
| 标准 | ¿Puedes ayudarme? |
| 更礼貌 | ¿Podrías ayudarme? |
| 非常礼貌 | ¿Pudieras ayudarme?（不太常见）|

📌 注意：
在当代西班牙语中，最常见的礼貌形式是条件式（podrías, deberías）和"quisiera"。用于礼貌的虚拟式过去未完成时在正式场合和拉丁美洲的一些地区更常见。

❌ 例子：
• Quisiera un café = 我想要一杯咖啡（非常礼貌）
• Quisiera pedir la cuenta = 我想结账`,
