        descripcion: `Estilo DIRECTO: repetir exactamente lo que alguien dijo.
• Ana dijo: "Tengo hambre".

Estilo INDIRECTO: contar lo que alguien dijo sin usar comillas.
• Ana dijo que tenía hambre.

🔹 VERBOS INTRODUCTORIOS:
• decir (que) = to say (that)
• contar (que) = to tell (that)
• preguntar (si) = to ask (if)
• pedir (que) = to ask for / to request
• responder (que) = to answer (that)
• explicar (que) = to explain (that)
• afirmar (que) = to affirm (that)
• negar (que) = to deny (that)

🔹 CAMBIOS PRINCIPALES:
1. Verbos de introducción
2. Conjunción "que" (para afirmaciones)
3. Cambios de persona, tiempo y lugar

📌 EJEMPLOS:
• María dice: 'Estudio español'. → María dice que estudia español.
• Carlos dijo: 'Voy al cine'. → Carlos dijo que iba al cine.

❌ ERROR COMÚN:
No olvides usar "que" después del verbo de introducción para afirmaciones.`,
        descripcionChino: `直接引语：逐字重复某人说的话。
- Ana dijo: "Tengo hambre". (安娜说："我饿了")

间接引语：转述某人说的话，不使用引号。
- Ana dijo que tenía hambre. (安娜说她饿了)

🔹 引导动词：
- decir (que) = 说
- contar (que) = 告诉
- preguntar (si) = 问（是否）
- pedir (que) = 请求
- responder (que) = 回答
- explicar (que) = 解释
- afirmar (que) = 断言
- negar (que) = 否认

🔹 主要变化：
1. 引导动词
2. 连词 "que"（用于陈述句）
3. 人称、时态和地点的变化

📌 例子：
- María dice: 'Estudio español'. → María dice que estudia español. (玛丽亚说她学西班牙语)
- Carlos dijo: 'Voy al cine'. → Carlos dijo que iba al cine. (卡洛斯说他去电影院)

❌ 常见错误：
在陈述句中，不要忘记在引导动词后使用"que"。`,
        ejemplos: [
          {
            espanol: "María dice: 'Estudio español'. → María dice que estudia español.",
            chino: "玛丽亚说：'我学西班牙语。' → 玛丽亚说她学西班牙语。",
          },
          {
            espanol: "Carlos dijo: 'Voy al cine'. → Carlos dijo que iba al cine.",
            chino: "卡洛斯说：'我去电影院。' → 卡洛斯说他去电影院。",
          },
        ],
