        id: "t3",
        titulo: "Preguntas en estilo indirecto",
        tituloChino: "间接引语中的问题",
        descripcion: `🔹 PREGUNTAS DE SÍ/NO (yes/no questions):
• Introduce con "preguntar si"
• "¿Tienes hambre?" → preguntó si tenía hambre.

🔹 PREGUNTAS CON PALABRA INTERROGATIVA (information questions):
• Introduce con "preguntar" + palabra interrogativa
• "¿Qué quieres?" → preguntó qué quería.
• "¿Dónde vives?" → preguntó dónde vivía.
• "¿Cómo te llamas?" → preguntó cómo se llamaba.
• "¿Cuándo llegas?" → preguntó cuándo llegaba.

🔹 PREGUNTAS EN PASADO:
• "¿Viniste ayer?" → preguntó si había venido el día anterior.
• "¿Dónde compraste eso?" → preguntó dónde había comprado eso.

📌 PALABRAS INTERROGATIVAS:
• qué = what
• quién = who
• dónde = where
• cuándo = when
• cómo = how
• por qué = why
• cuánto = how much

📌 EJEMPLOS:
• Preguntó: '¿Vienes?' → Preguntó si venía.
• Preguntó: '¿Dónde vives?' → Preguntó dónde vivía.

❌ ERROR COMÚN:
No uses "que" en preguntas indirectas. Usa "si" para preguntas de sí/no y la palabra interrogativa para las demás.`,
        descripcionChino: `🔹 是否问句：
- 使用 "preguntar si" 引导
- "¿Tienes hambre?" (你饿吗？) → preguntó si tenía hambre. (他问是否饿了)

🔹 特殊疑问句：
- 使用 "preguntar" + 疑问词引导
- "¿Qué quieres?" (你想要什么？) → preguntó qué quería. (他问了要什么)
- "¿Dónde vives?" (你住在哪里？) → preguntó dónde vivía. (他问了住在哪里)
- "¿Cómo te llamas?" (你叫什么名字？) → preguntó cómo se llamaba. (他问了叫什么名字)
- "¿Cuándo llegas?" (你什么时候到？) → preguntó cuándo llegaba. (他问了什么时候到)

🔹 过去时的问题：
- "¿Viniste ayer?" (你昨天来了吗？) → preguntó si había venido el día anterior. (他问是否前一天来了)
- "¿Dónde compraste eso?" (你在哪里买的那个？) → preguntó dónde había comprado eso. (他问在哪里买了那个)

📌 疑问词：
- qué = 什么
- quién = 谁
- dónde = 哪里
- cuándo = 什么时候
- cómo = 怎么
- por qué = 为什么
- cuánto = 多少

📌 例子：
• Preguntó: '¿Vienes?' → Preguntó si venía. = 他问：'你来吗？' → 他问他是否来。
• Preguntó: '¿Dónde vives?' → Preguntó dónde vivía. = 他问：'你住在哪里？' → 他问他住在哪里。

❌ 常见错误：
不要在间接疑问句中使用"que"。是否问句用"si"，其他问句用疑问词。`,
