        id: "t4",
        titulo: "Peticiones, consejos y órdenes",
        tituloChino: "请求、建议和命令",
        descripcion: `🔹 PETICIONES (requests):
• Introduce con "pedir que" + subjuntivo
• "¡Ayúdame!" → pidió que le ayudara.
• "Por favor, ven" → pidió que fuera.

🔹 CONSEJOS (advice):
• Introduce con "aconsejar que" + subjuntivo
• "Debes estudiar" → aconsejó que estudiara.
• "Sería mejor que descansaras" → aconsejó que descansara.

🔹 ÓRDENES (orders):
• Introduce con "decir que" + subjuntivo
• "¡Sal de aquí!" → dijo que saliera de allí.
• "¡Cállate!" → dijo que se callara.
• "¡Ven aquí!" → dijo que viniera allí.

🔹 OFRECIMIENTOS Y SUGERENCIAS:
• "¿Quieres que te ayude?" → ofreció ayudarle.
• "¿Por qué no descansas?" → sugirió que descansara.

📌 VERBOS QUE RIGEN SUBJUNTIVO EN ESTILO INDIRECTO:
• pedir que
• aconsejar que
• recomendar que
• sugerir que
• prohibir que
• ordenar que
• exigir que

📌 EJEMPLOS:
• Me pidió que le ayudara.
• Me aconsejó que estudiara más.
• El jefe ordenó que terminaran el informe.

❌ ERROR COMÚN:
No olvides usar el subjuntivo después de "pedir que", "aconsejar que", etc.`,
        descripcionChino: `🔹 请求：
- 使用 "pedir que" + 虚拟式引导
- "¡Ayúdame!" (帮我！) → pidió que le ayudara. (他请求帮他)
- "Por favor, ven" (请来) → pidió que fuera. (他请求去)

🔹 建议：
- 使用 "aconsejar que" + 虚拟式引导
- "Debes estudiar" (你应该学习) → aconsejó que estudiara. (他建议学习)
- "Sería mejor que descansaras" (你最好休息) → aconsejó que descansara. (他建议休息)

🔹 命令：
- 使用 "decir que" + 虚拟式引导
- "¡Sal de aquí!" (出去！) → dijo que saliera de allí. (他说让他出去)
- "¡Cállate!" (闭嘴！) → dijo que se callara. (他说让他闭嘴)
- "¡Ven aquí!" (过来！) → dijo que viniera allí. (他说让他过来)

🔹 提议和暗示：
- "¿Quieres que te ayude?" (你想让我帮你吗？) → ofreció ayudarle. (他主动提出帮忙)
- "¿Por qué no descansas?" (你为什么不休息？) → sugirió que descansara. (他建议休息)

📌 在间接引语中带虚拟式的动词：
- pedir que = 请求
- aconsejar que = 建议
- recomendar que = 推荐
- sugerir que = 暗示
- prohibir que = 禁止
- ordenar que = 命令
- exigir que = 要求

📌 例子：
• Me pidió que le ayudara. = 他请求我帮助他。
• Me aconsejó que estudiara más. = 他建议我多学习。
• El jefe ordenó que terminaran el informe. = 老板命令他们完成报告。

❌ 常见错误：
不要忘记在"pedir que"、"aconsejar que"等后面使用虚拟式。`,
