        descripcion: `Expresiones muy comunes con TENER:

🔹 ESTADOS FÍSICOS Y EMOCIONES:
• tener hambre = to be hungry
• tener sed = to be thirsty
• tener sueño = to be sleepy
• tener calor = to be hot
• tener frío = to be cold
• tener prisa = to be in a hurry
• tener suerte = to be lucky
• tener cuidado = to be careful
• tener razón = to be right
• tener miedo = to be afraid
• tener vergüenza = to be embarrassed / ashamed
• tener esperanza = to have hope
• tener confianza = to have confidence

🔹 DESEOS Y SENTIMIENTOS:
• tener ganas de = to feel like (doing something)
• tener celos = to be jealous
• tener envidia = to be envious
• tener paciencia = to have patience

🔹 RELACIONES:
• tener éxito = to be successful
• tener problemas = to have problems
• tener la culpa = to be guilty / to blame

📌 EJEMPLOS:
• Tengo mucha hambre.
• ¡Ten cuidado con el coche!
• Tienes razón, lo siento.
• Tengo ganas de comer pizza.

❌ ERROR COMÚN:
No uses "ser" o "estar" para expresar hambre, sed, etc. Siempre usa "tener".`,
        descripcionChino: `带有TENER的非常常见的表达：

🔹 身体状态和情绪：
• tener hambre = 饿了
• tener sed = 渴了
• tener sueño = 困了
• tener calor = 热
• tener frío = 冷
• tener prisa = 赶时间
• tener suerte = 幸运
• tener cuidado = 小心
• tener razón = 有道理/正确
• tener miedo = 害怕
• tener vergüenza = 尴尬/羞愧
• tener esperanza = 有希望
• tener confianza = 有信心

🔹 愿望和感受：
• tener ganas de = 想要/想做某事
• tener celos = 嫉妒
• tener envidia = 羡慕
• tener paciencia = 有耐心

🔹 关系：
• tener éxito = 成功
• tener problemas = 有问题
• tener la culpa = 有罪/有责任

📌 例子：
• Tengo mucha hambre. = 我很饿。
• ¡Ten cuidado con el coche! = 小心车！
• Tienes razón, lo siento. = 你有道理，对不起。
• Tengo ganas de comer pizza. = 我想吃披萨。

❌ 常见错误：
不要用"ser"或"estar"来表达饥饿、口渴等。总是使用"tener"。`,
