        tituloChino: "带有'dar'和'echar'的表达",
        descripcion: `🔹 EXPRESIONES CON DAR (expressions with dar):

• dar la hora = to tell the time
• dar las gracias = to thank
• dar un paseo = to take a walk
• dar vergüenza = to be embarrassing
• dar miedo = to be scary
• dar igual = to not matter
• dar un beso = to give a kiss
• dar un abrazo = to give a hug
• dar la lata = to be annoying
• dar en el clavo = to hit the nail on the head

🔹 EXPRESIONES CON ECHAR (expressions with echar):

• echar de menos = to miss (someone/something)
• echar un vistazo = to take a look
• echar la culpa = to blame
• echar una mano = to lend a hand
• echarse a reír = to burst out laughing
• echarse a llorar = to burst into tears
• echar un ojo = to keep an eye on
• echar gasolina = to put gasoline
• echar una siesta = to take a nap

📌 EJEMPLOS:
• Te echo de menos.
• Échale un vistazo a este documento.
• No me eches la culpa.

❌ NOTA:
"Echar de menos" es una expresión muy común que no tiene equivalente literal en inglés. Significa "extrañar".`,
        descripcionChino: `🔹 带有DAR的表达：
• dar la hora = 报时
• dar las gracias = 感谢
• dar un paseo = 散步
• dar vergüenza = 让人害羞
• dar miedo = 让人害怕
• dar igual = 无所谓
• dar un beso = 亲吻
• dar un abrazo = 拥抱
• dar la lata = 烦人
• dar en el clavo = 一针见血

🔹 带有ECHAR的表达：
• echar de menos = 想念
• echar un vistazo = 看一眼
• echar la culpa = 责备
• echar una mano = 帮忙
• echarse a reír = 笑起来
• echarse a llorar = 哭起来
• echar un ojo = 照看/留意
• echar gasolina = 加油
• echar una siesta = 午睡

📌 例子：
• Te echo de menos. = 我想你。
• Échale un vistazo a este documento. = 看一眼这个文件。
• No me eches la culpa. = 别怪我。

❌ 注意：
"Echar de menos"是一个非常常见的表达，在英语中没有字面等效的表达。意思是"想念"。`,
