    tituloChino: "假朋友 - 容易混淆的词",
    descripcion: "学习西班牙语中与英语相似但意思不同的单词，避免常见错误。",
    descripcionChino: "学习西班牙语中与英语相似但意思不同的单词，避免常见错误",
