        id: "t4",
        titulo: "Estructuras temporales complejas",
        tituloChino: "复杂的时间结构",
        descripcion: `🔹 ACCIONES SIMULTÁNEAS (simultaneous actions):
• Mientras + imperfecto / presente, + imperfecto / presente
  Ejemplo: Mientras estudiaba, escuchaba música.

🔹 ACCIONES SUCESIVAS (successive actions):
• Primero... luego... después... finalmente...
  Ejemplo: Primero me levanto, luego desayuno, después me ducho y finalmente salgo.

🔹 ACCIONES ANTERIORES (previous actions):
• Antes de + infinitivo / antes de que + subjuntivo
  Ejemplo: Antes de salir, desayuno.

🔹 ACCIONES POSTERIORES (later actions):
• Después de + infinitivo / después de que + subjuntivo
  Ejemplo: Después de comer, salgo a pasear.

🔹 ACCIONES QUE TERMINAN (actions that end):
• Hasta que + subjuntivo
  Ejemplo: Esperaré hasta que llegues.

🔹 ACCIONES QUE COMIENZAN (actions that start):
• Desde que + subjuntivo / indicativo
  Ejemplo: Desde que te conocí, soy más feliz.

🔹 ACCIONES INMEDIATAS (immediate actions):
• En cuanto / tan pronto como / nada más + subjuntivo
  Ejemplo: En cuanto llegue, te llamo.

📌 EJEMPLOS COMPLETOS:
• Primero me levanto, luego me ducho, después desayuno y finalmente salgo de casa.
• No me iré hasta que termine el trabajo.
• Desde que empecé a estudiar español, he aprendido mucho.
• Tan pronto como pueda, te ayudaré.`,
        descripcionChino: `🔹 同时发生的动作：
• Mientras + 过去未完成时/现在时 + 过去未完成时/现在时
  例子：Mientras estudiaba, escuchaba música. = 我学习的时候听音乐。

🔹 相继发生的动作：
• Primero... luego... después... finalmente...
  例子：Primero me levanto, luego desayuno, después me ducho y finalmente salgo. = 首先我起床，然后吃早餐，之后淋浴，最后出门。

🔹 先发生的动作：
• Antes de + 动词原形 / antes de que + 虚拟式
  例子：Antes de salir, desayuno. = 出门前，我吃早餐。

🔹 后发生的动作：
• Después de + 动词原形 / después de que + 虚拟式
  例子：Después de comer, salgo a pasear. = 吃完饭后，我出去散步。

🔹 结束的动作：
• Hasta que + 虚拟式
  例子：Esperaré hasta que llegues. = 我会等到你来。

🔹 开始的动作：
• Desde que + 虚拟式/陈述式
  例子：Desde que te conocí, soy más feliz. = 自从认识你，我更快乐了。

🔹 立即发生的动作：
• En cuanto / tan pronto como / nada más + 虚拟式
  例子：En cuanto llegue, te llamo. = 我一到就打电话给你。

📌 完整例子：
• Primero me levanto, luego me ducho, después desayuno y finalmente salgo de casa. = 首先我起床，然后淋浴，之后吃早餐，最后出门。
• No me iré hasta que termine el trabajo. = 我不会离开，直到工作完成。
• Desde que empecé a estudiar español, he aprendido mucho. = 自从我开始学西班牙语，我学到了很多。
• Tan pronto como pueda, te ayudaré. = 我一有可能就会帮你。`,
