        descripcion: `🔹 COMPRAR EN EL MERCADO (buying at the market):

PREGUNTAR POR PRODUCTOS:
• ¿Cuánto cuesta el kilo de...?
• ¿A cómo están las manzanas?
• ¿Tiene tomates frescos?
• ¿De dónde son estas naranjas?

PEDIR CANTIDADES:
• Deme medio kilo de...
• Quiero un kilo de...
• Póngame doscientos gramos de...
• Una docena de huevos, por favor.

FRASES ÚTILES:
• ¿Me puede dar una bolsa?
• ¿Acepta tarjeta o solo efectivo?
• ¿Me hace un descuento?
• Es muy caro. ¿Puede rebajarlo?

RESPUESTAS DEL VENDEDOR:
• Son deliciosos, pruébelos.
• A tres euros el kilo.
• Es un poco caro porque son ecológicos.
• Le puedo dejar a dos euros.

📌 NOTA CULTURAL:
En los mercados españoles, es común regatear (negociar el precio) en algunos puestos, especialmente en mercados municipales o al aire libre. Sin embargo, en supermercados y tiendas grandes no se puede regatear.

📌 EJEMPLOS:
• ¿Cuánto cuesta el kilo de naranjas?
• Deme medio kilo de jamón, por favor.
• ¿Me hace un descuento si llevo dos kilos?`,
        descripcionChino: `🔹 在市场购物：

询问产品：
• ¿Cuánto cuesta el kilo de...? = ...多少钱一公斤？
• ¿A cómo están las manzanas? = 苹果怎么卖？
• ¿Tiene tomates frescos? = 有新鲜的西红柿吗？
• ¿De dónde son estas naranjas? = 这些橙子来自哪里？

询问数量：
• Deme medio kilo de... = 给我半公斤...
• Quiero un kilo de... = 我想要一公斤...
• Póngame doscientos gramos de... = 给我两百克...
• Una docena de huevos, por favor. = 请给我一打鸡蛋。

有用句子：
• ¿Me puede dar una bolsa? = 能给我一个袋子吗？
• ¿Acepta tarjeta o solo efectivo? = 收卡还是只收现金？
• ¿Me hace un descuento? = 能给我打折吗？
• Es muy caro. ¿Puede rebajarlo? = 太贵了。能便宜点吗？

售货员的回答：
• Son deliciosos, pruébelos. = 很美味，尝尝看。
• A tres euros el kilo. = 每公斤三欧元。
• Es un poco caro porque son ecológicos. = 有点贵因为是有机的。
• Le puedo dejar a dos euros. = 我可以给您两欧元。

📌 文化提示：
在西班牙的市场，在某些摊位讨价还价是常见的，尤其是在市政市场或露天市场。然而，在超市和大商店不能讨价还价。

📌 例子：
• ¿Cuánto cuesta el kilo de naranjas? = 橙子一公斤多少钱？
• Deme medio kilo de jamón, por favor. = 请给我半公斤火腿。
• ¿Me hace un descuento si llevo dos kilos? = 如果我买两公斤能打折吗？`,
